function Read-Hidden([string]$l){$s=Read-Host $l -AsSecureString;try{if($s.Length-eq0){throw 'Empty value.'};$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($s);try{[Runtime.InteropServices.Marshal]::PtrToStringBSTR($p)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p)}}finally{$s.Dispose()}}
function Sha256([string]$v){$h=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($v)))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}}
function Assert-Checks([object]$r,[string]$l){$bad=@();foreach($p in $r.checks.PSObject.Properties){if([bool]$p.Value){Write-Output "PASS guard=$l.$($p.Name)"}else{$bad+=@($p.Name);[Console]::Error.WriteLine("FAIL guard=$l.$($p.Name)")}};if($bad.Count-ne0-or-not[bool]$r.all_checks_pass){throw "$l failed $($bad.Count) guard(s)."}}
function Login([string]$e,[string]$p){$q=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Post,'/auth/v1/token?grant_type=password');try{$q.Content=[Net.Http.StringContent]::new((ConvertTo-Json @{email=$e;password=$p}-Compress),[Text.Encoding]::UTF8,'application/json');$x=$script:client.SendAsync($q).GetAwaiter().GetResult();try{if(-not$x.IsSuccessStatusCode){throw "Login HTTP $([int]$x.StatusCode)"};$b=$x.Content.ReadAsStringAsync().GetAwaiter().GetResult()|ConvertFrom-Json;[pscustomobject]@{Id=[guid]$b.user.id;Token=[string]$b.access_token}}finally{$x.Dispose()}}finally{$q.Dispose()}}
function SendAs([string]$t,[string]$a,[object]$r){$q=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Post,'/rest/v1/rpc/task_dispatch');try{$q.Headers.Add('Content-Profile','reivro_checks_api');$q.Headers.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$t);$q.Content=[Net.Http.StringContent]::new((ConvertTo-Json @{action=$a;request=$r}-Depth 40 -Compress),[Text.Encoding]::UTF8,'application/json');$x=$script:client.SendAsync($q).GetAwaiter().GetResult();try{[pscustomobject]@{Status=[int]$x.StatusCode;Body=$x.Content.ReadAsStringAsync().GetAwaiter().GetResult()}}finally{$x.Dispose()}}finally{$q.Dispose()}}
function PsqlJson([string]$f,[hashtable]$x){$op=[Environment]::GetEnvironmentVariable('PGPASSWORD','Process');$oc=[Environment]::GetEnvironmentVariable('PGSSLROOTCERT','Process');try{$env:PGPASSWORD=$script:dbPassword;$env:PGSSLROOTCERT=$script:ca;$a=@('-X','-w','-qAt','-v','ON_ERROR_STOP=1','-d','host=aws-1-us-west-1.pooler.supabase.com port=5432 user=postgres.lbklqqqbmeyseeccdqog dbname=postgres sslmode=verify-full','-v',"repository_id=$($script:planDoc.repository_id)",'-v',"first_submission_id=$($script:planDoc.submission_id)",'-v',"second_submission_id=bd30c2f8-3702-4fe1-a1b4-f6a1f18019bf",'-v',"third_submission_id=$($script:thirdReceipt.submission_id)",'-v',"new_contract_id=$script:contractId",'-v',"new_submission_id=$script:submissionId",'-v',"base_sha=$($script:planDoc.base_sha)",'-v',"head_sha=$($script:planDoc.head_sha)");foreach($k in $x.Keys){$a+=@('-v',"$k=$($x[$k])")};$a+=@('-f',$f);$o=& $script:psql @a;if($LASTEXITCODE-ne 0){throw "psql exited $LASTEXITCODE"};$j=@($o|Where-Object{$_ -match '^\{'});if($j.Count-ne 1){throw 'Expected one JSON record.'};$j[0]|ConvertFrom-Json}finally{if($null-eq $op){Remove-Item Env:PGPASSWORD -ErrorAction SilentlyContinue}else{$env:PGPASSWORD=$op};if($null-eq $oc){Remove-Item Env:PGSSLROOTCERT -ErrorAction SilentlyContinue}else{$env:PGSSLROOTCERT=$oc}}}
function Invoke-Race([Net.Http.HttpClient]$c,[string]$t,[hashtable]$payloads){$pool=[RunspaceFactory]::CreateRunspacePool(1,3);$pool.Open();$ready=[Threading.CountdownEvent]::new(3);$gate=[Threading.ManualResetEventSlim]::new($false);$jobs=@();$code={param($client,$token,$action,$json,$r,$g);[void]$r.Signal();if(-not$g.Wait(10000)){throw 'Barrier timeout'};$q=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Post,'/rest/v1/rpc/task_dispatch');try{$q.Headers.Add('Content-Profile','reivro_checks_api');$q.Headers.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$token);$q.Content=[Net.Http.StringContent]::new($json,[Text.Encoding]::UTF8,'application/json');$x=$client.SendAsync($q).GetAwaiter().GetResult();try{$body=$x.Content.ReadAsStringAsync().GetAwaiter().GetResult();$state=$null;if([int]$x.StatusCode-ge200-and[int]$x.StatusCode-lt300){try{$state=[string](($body|ConvertFrom-Json).state)}catch{}};[pscustomobject]@{Action=$action;Status=[int]$x.StatusCode;Success=([int]$x.StatusCode-ge200-and[int]$x.StatusCode-lt300);State=$state}}finally{$x.Dispose()}}finally{$q.Dispose()}}
 try{foreach($action in @('renew','fail','finish')){$ps=[PowerShell]::Create();$ps.RunspacePool=$pool;[void]$ps.AddScript($code).AddArgument($c).AddArgument($t).AddArgument($action).AddArgument($payloads[$action]).AddArgument($ready).AddArgument($gate);$jobs+=,[pscustomobject]@{P=$ps;H=$ps.BeginInvoke()}};if(-not $ready.Wait(10000)){throw 'Race workers missed barrier.'};$gate.Set();$out=@();foreach($j in $jobs){$out+=@($j.P.EndInvoke($j.H));if($j.P.HadErrors){throw 'Race worker failed.'}};$out}finally{$gate.Dispose();$ready.Dispose();foreach($j in $jobs){$j.P.Dispose()};$pool.Close();$pool.Dispose()}}
