try{
 $shared=Join-Path $PSScriptRoot 'ReivroFinalPlanValidation.ps1';$classifier=Join-Path $PSScriptRoot 'ReivroRenewFailFinishClassification.ps1';$pre=Join-Path $PSScriptRoot 'preflight_staging_renew_fail_finish_gate.sql';$check=Join-Path $PSScriptRoot 'checkpoint_staging_renew_fail_finish_gate.sql';$post=Join-Path $PSScriptRoot 'postcheck_staging_renew_fail_finish_gate.sql';$rec=Join-Path $PSScriptRoot 'reconcile_staging_renew_fail_finish_gate.sql';$cert=if([string]::IsNullOrWhiteSpace($CaPath)){Join-Path $HOME 'Downloads\prod-ca-2021.crt'}else{$CaPath}
