 $psql=(Resolve-Path (Join-Path $PgBin 'psql.exe')).Path;if((& $psql --version)-notmatch 'PostgreSQL\)\s+19'){throw 'PostgreSQL 19 required.'};$git=@(Get-Command git -CommandType Application)[0].Source;$ca=(Resolve-Path $cert).Path;$origin=(& $git -C $Repository remote get-url origin).Trim();if($origin-cnotmatch '(?i)(?:github\.com[/:])sovereis/REIVRO(?:\.git)?$'){throw 'Unexpected Git origin.'}
