 $stage='preflight';$scope=PsqlJson $pre @{};Assert-Checks $scope preflight;Add-Type -AssemblyName System.Net.Http;$handler=[Net.Http.HttpClientHandler]::new();$handler.MaxConnectionsPerServer=8;$client=[Net.Http.HttpClient]::new($handler);$client.BaseAddress=[uri]'https://lbklqqqbmeyseeccdqog.supabase.co';$client.DefaultRequestHeaders.Add('apikey',$key);$reviewer=Login $re $rp;$agent=Login $ae $ap;$worker=Login $we $wp;if($reviewer.Id-ne[guid]$scope.reviewer_id-or$agent.Id-ne[guid]$scope.agent_id-or$worker.Id-ne[guid]$scope.worker_id){throw 'Identity mismatch.'};$re=$rp=$ae=$ap=$we=$wp=$key=$null
