 $claimReq=@{repository_id=[long]$planDoc.repository_id;installation_id=[long]$scope.installation_id;repository=[string]$scope.repository;base_ref=[string]$scope.base_ref;id=$submissionId;delivery=$submissionId;pr=4;base_sha=[string]$planDoc.base_sha;head_sha=[string]$planDoc.head_sha;digest=$digest;verifier='task-completion-v1'};$x=SendAs $worker.Token claim $claimReq;if($x.Status-lt200-or$x.Status-ge300){throw 'Claim failed.'};$claim=$x.Body|ConvertFrom-Json;if($claim.state-cne'running'-or[int]$claim.fence-ne1){throw 'Claim shape.'};$saved=PsqlJson $check @{new_digest=$digest;expected_events=47;run_id=$claim.run_id;attempt_id=$claim.attempt_id};Assert-Checks $saved checkpoint47
 $result=[ordered]@{status='VERIFIED';base_sha=[string]$planDoc.base_sha;head_sha=[string]$planDoc.head_sha;digest=$digest;verifier='task-completion-v1';evidence=$evidence;policy_set=$claim.policy_set};$common=@{repository_id=[long]$planDoc.repository_id;installation_id=[long]$scope.installation_id;id=$submissionId;run_id=$claim.run_id;attempt_id=$claim.attempt_id;fence=1};$finish=$common.Clone();$finish.result=$result;$payloads=@{renew=(ConvertTo-Json @{action='renew';request=$common}-Depth 40 -Compress);fail=(ConvertTo-Json @{action='fail';request=$common}-Depth 40 -Compress);finish=(ConvertTo-Json @{action='finish';request=$finish}-Depth 40 -Compress)}
 $stage='race';$responses=@(Invoke-Race $client $worker.Token $payloads);$classification=Get-ReivroRenewFailFinishClassification $responses;if(-not$classification.Pass){throw "Race classification failed: renew=$($classification.RenewSuccess) fail=$($classification.FailSuccess) finish=$($classification.FinishSuccess)"};$sanitized=@($responses|ForEach-Object{[ordered]@{action=$_.Action;status=$_.Status;success=$_.Success;state=$_.State}});$saved=PsqlJson $post @{};Assert-Checks $saved postcheck;if([int]$saved.journal-ne[int]$classification.ExpectedJournal-or[string]$saved.state-cne[string]$classification.ExpectedState){throw 'Persisted classification mismatch.'};[ordered]@{state='RENEW_FAIL_FINISH_RACE_PASS';submission_id=$submissionId;run_id=$claim.run_id;responses=$sanitized;journal=$saved.journal;final_state=$saved.state}|ConvertTo-Json -Depth 10|Set-Content $receipt -Encoding UTF8;Write-Output 'RENEW_FAIL_FINISH_SINGLE_CLOSER_PASS'
}catch{[Console]::Error.WriteLine("FAIL stage=$stage type=$($_.Exception.GetType().Name) message=$($_.Exception.Message)");if($writeStarted){try{$r=PsqlJson $rec @{};[Console]::Error.WriteLine(('RECONCILIATION '+(ConvertTo-Json $r -Depth 20 -Compress)))}catch{[Console]::Error.WriteLine('READ-ONLY RECONCILIATION FAILED.')}};exit 1}finally{$key=$dbPassword=$approval=$null;if($null-ne$reviewer){$reviewer.Token=$null};if($null-ne$agent){$agent.Token=$null};if($null-ne$worker){$worker.Token=$null};Remove-Item Env:PGPASSWORD,Env:PGSSLROOTCERT -ErrorAction SilentlyContinue;if($null-ne$client){$client.Dispose()}elseif($null-ne$handler){$handler.Dispose()}}
